+          expect(File('${sandbox.path}/$ipaRel').existsSync(), isTrue);
+          // …a valid zip with Symbols/ gone…
+          final entries = ipaEntries();
+          expect(entries.where((n) => n.startsWith('Symbols/')), isEmpty);
