+# gh-1403 test shim: translate the BSD form, forward everything else.
+stat() {
+  if [ "\${1:-}" = "-f%z" ]; then
+    /usr/bin/stat -c%s "\$2" 2>/dev/null || /usr/bin/stat -f%z "\$2"
+  else
+    /usr/bin/stat "\$@"
+  fi
