+      /// The entries of the sandbox IPA after the step ran.
+      List<String> ipaEntries() => ZipDecoder()
+          .decodeBytes(File('${sandbox.path}/$ipaRel').readAsBytesSync())
+          .files
+          .map((f) => f.name)
+          .toList();
